import 'dart:convert'; import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import '../providers/app_state.dart';
class SettingsScreen extends StatelessWidget{final AppState state;const SettingsScreen({super.key,required this.state});Future<void> saveMode(ThemeMode m)async{final p=await SharedPreferences.getInstance();await p.setString('themeMode',m.name);state.setTheme(m);} @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(24),children:[Text('Settings',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:18),Card(child:Column(children:[const ListTile(title:Text('Appearance',style:TextStyle(fontWeight:FontWeight.bold))),RadioListTile(value:ThemeMode.system,groupValue:state.themeMode,onChanged:(v)=>saveMode(v!),title:const Text('System')),RadioListTile(value:ThemeMode.light,groupValue:state.themeMode,onChanged:(v)=>saveMode(v!),title:const Text('Light')),RadioListTile(value:ThemeMode.dark,groupValue:state.themeMode,onChanged:(v)=>saveMode(v!),title:const Text('Dark'))])),const SizedBox(height:12),Card(child:ListTile(title:const Text('Accent color'),subtitle:Wrap(spacing:8,children:[for(final col in [Colors.green,Colors.blue,Colors.purple,Colors.orange,Colors.teal])IconButton(onPressed:()=>state.setAccent(col),icon:CircleAvatar(backgroundColor:col,radius:12))]))),const SizedBox(height:12),Card(child:Column(children:[const ListTile(title:Text('Data',style:TextStyle(fontWeight:FontWeight.bold))),ListTile(leading:const Icon(Icons.upload_file),title:const Text('Export JSON'),onTap:()async{final p=await SharedPreferences.getInstance();await p.setString('lastExport',jsonEncode(state.workspace.toJson()));}),ListTile(leading:const Icon(Icons.delete_forever),title:const Text('Delete all data'),onTap:()async{await state.repo.clear();} )])),const SizedBox(height:12),const Card(child:ListTile(title:Text('About'),subtitle:Text('Task Manager 1.0.0 · GitHub-inspired, local-first Flutter app')))]);}
